"""

    Create a basic sequence with the given pieces.

    Keyword arguments:

    piece_dict -- The pieces dictionary with the quantity of each piece.

    """
def basic_sequence(piece_dict: Any) -> object {
    sequence = [];
    for (piece, number) in piece_dict.items() {
        if (number < 1) {
            continue;
        }
        times = ("%s " % piece) * number;
        sequence.extend(times.split());
    }
    return sequence;
}

"""
    :param x: string
    :param y: string
    :return:
    """
def string_rotation(x: Any, y: Any) -> object {
    if (len(x) != len(y)) {
        return False;
    }
    new_str = x + x;
    if (y in new_str) {
        return True;
    }
    return False;
}

"""find_lcs"""
def find_lcs(s1: Any, s2: Any) -> object {
    m = [[0 for i in range((len(s2) + 1))] for j in range((len(s1) + 1))];
    mmax = 0;
    p = 0;
    for i in range(len(s1)) {
        for j in range(len(s2)) {
            if (s1[i] == s2[j]) {
                m[(i + 1)][(j + 1)] = m[i][j] + 1;
                if (m[(i + 1)][(j + 1)] > mmax) {
                    mmax = m[(i + 1)][(j + 1)];
                    p = i + 1;
                }
            }
        }
    }
    return (s1[(p - mmax):p], mmax);
}

