    Returns A list of pi expressions
    -------

    """
def str_to_pi_list(inp: Any) -> object {
    lines = inp.strip().splitlines();
    lis = [];
    for line in lines {
        if (line == "None") {
            return [];
        }
        lis.append(line);
    }
    return lis;
}

"""Checks whether `chars` is a whitespace character."""
def is_whitespace(char: Any) -> object {
    import unicodedata;
    if ((char == " ") or (char == "\t") or (char == "\n") or (char == "\r")) {
        return True;
    }
    cat = unicodedata.category(char);
    if (cat == "Zs") {
        return True;
    }
    return False;
}

""" This will calculate the address class of the IP address based on bits of binary string
			A: 0...
			B: 10..
			C: 110.
			D: 1110
			E: 1111
	"""
def getAddressClass(binaryString: Any) -> object {
    addressClass = "";
    if (binaryString[0] == "0") {
        addressClass = "A";
    } elif (binaryString[0:2] == "10") {
        addressClass = "B";
    } elif (binaryString[0:3] == "110") {
        addressClass = "C";
    } elif (binaryString[0:4] == "1110") {
        addressClass = "D";
    } elif (binaryString[0:4] == "1111") {
        addressClass = "E";
    }
    return addressClass;
}

"""
    Function for providing single format for MAC addresses.

    :param str mac_address: MAC address to be converted.
    :return: MAC address in format `XX:XX:XX:XX:XX:XX`.
    """
def mac_addr_convert(mac_address: Any = "") -> object {
    try {
        mac = mac_address.replace(".", "");
        mac = [mac[i:(i + 2)].upper() for i in range(0, len(mac), 2)];
        mac = ":".join(mac);
        return mac;
    } except Exception as e {
        return mac_address;
    }
}

"""
    HSW (Hamaus-Sutter-Wendelt) function for the universal void density profile
    See: Hamaus et al. (2014)
    """
def HSW_offset(
    r: Any, rs: Any, alpha: Any, Rv: Any, beta: Any, deltac: Any, offset: Any
) -> object {
    numerator = 1 - ((r / rs) ** alpha);
    denominator = 1 + ((r / Rv) ** beta);
    return (((deltac * numerator) / denominator) + offset);
}
